const PROMPT = $('Config').first().json.prompt;
const body = $input.first().json.body || {};
const text = String(body.text || '').slice(0, 10000);
const channel = String(body.channel || 'call');
if (!text.trim()) return [{ json: { error: 'text is required' } }];
return [{ json: { anthropic: {
  model: 'claude-haiku-5-5',
  max_tokens: 500,
  system: PROMPT,
  messages: [{ role: 'user', content: `Channel: ${channel}\n\nTranscript or message so far:\n\n${text}` }]
}}}];

const raw = ($input.first().json.content || []).map(c => c.text || '').join('');
let v = {};
try { v = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { v = { probability: 0, reason: 'Claude answered in an unexpected format.', tactics: [] }; }
const p = Math.max(0, Math.min(1, Number(v.probability) || 0));
return [{ json: {
  score: Math.round(p * 100),
  probability: p,
  scenario: v.scenario || 'other',
  tactics: Array.isArray(v.tactics) ? v.tactics : [],
  reason: v.reason || '',
  advice: v.advice || '',
  warning: v.warning || '',
  engine: 'claude-haiku-5-5 via n8n'
}}];
